#!/bin/bash
# fetch-openssl.sh: download the upstream OpenSSL 1.0.1u tarball that the external/openssl import (series
# external_openssl/0002, regenerated by mkimport.sh) is made from, and check it against the pinned sha256.
#
#   fetch-openssl.sh [--out DIR]     prints the path of the checked tarball on stdout, exit 0
#   fetch-openssl.sh --selftest      offline checks of the download/cache logic (file:// URLs, synthetic tarballs)
#   . fetch-openssl.sh               defines the pin (OPENSSL_TAR_NAME, OPENSSL_TAR_URL, TAR_SHA256) and fetch_tarball
#
# DIR defaults to ./dl. A file DIR/openssl-1.0.1u.tar.gz with the pinned sha256 is reused without network access; one with
# another sha256 is deleted and downloaded again. The download goes to DIR/openssl-1.0.1u.tar.gz.part (curl --fail) and is
# renamed only after its sha256 matched; a failed or mismatching download is deleted, nothing is left behind.
# OPENSSL_TAR_URL may be overridden from the environment (a mirror, or file:// in tests); the sha256 cannot.
# Exit 1 = download failed or sha256 mismatch, 2 = usage.
# SPDX-License-Identifier: Apache-2.0
OPENSSL_TAR_NAME=openssl-1.0.1u.tar.gz
OPENSSL_TAR_URL=${OPENSSL_TAR_URL:-https://www.openssl.org/source/old/1.0.1/$OPENSSL_TAR_NAME}
TAR_SHA256=4312b4ca1215b6f2c97007503d80db80d5157f76f8f7d3febbe6b4c56ff26739   # published openssl-1.0.1u.tar.gz.sha256

# fetch_tarball URL SHA256 DIR NAME: prints DIR/NAME once it holds a file with SHA256; rc 1 (message on stderr) otherwise.
fetch_tarball() {
  local url=$1 sha=$2 dir=$3 name=$4 f part got
  f=$dir/$name; part=$f.part
  mkdir -p "$dir" || { echo "fetch-openssl: cannot create $dir" >&2; return 1; }
  if [ -f "$f" ]; then
    got=$(sha256sum "$f" | cut -d' ' -f1)
    if [ "$got" = "$sha" ]; then echo "fetch-openssl: reusing $f (sha256 ok)" >&2; printf '%s\n' "$f"; return 0; fi
    echo "fetch-openssl: cached $f has sha256 $got, not $sha: deleting it" >&2
    rm -f "$f"
  fi
  rm -f "$part"
  echo "fetch-openssl: downloading $url" >&2
  if ! curl --fail --location --silent --show-error --proto '=https,file' --output "$part" "$url"; then
    rm -f "$part"; echo "fetch-openssl: download of $url failed" >&2; return 1
  fi
  got=$(sha256sum "$part" | cut -d' ' -f1)
  if [ "$got" != "$sha" ]; then
    rm -f "$part"; echo "fetch-openssl: sha256 of the download is $got, not $sha: deleted" >&2; return 1
  fi
  mv -f "$part" "$f" || { rm -f "$part"; return 1; }
  printf '%s\n' "$f"
}

# Sourced: only the pin and the function.
[ "${BASH_SOURCE[0]}" = "$0" ] || return 0
set -uo pipefail

selftest() {
  local t pass=0 fail=0 out rc good goodsha bad
  t=$(mktemp -d) || exit 1
  trap "rm -rf '$t'" EXIT
  mkdir "$t/src"
  printf 'good tarball\n' > "$t/src/good.tar.gz"; goodsha=$(sha256sum "$t/src/good.tar.gz" | cut -d' ' -f1)
  printf 'tampered tarball\n' > "$t/src/bad.tar.gz"; bad=file://$t/src/bad.tar.gz; good=file://$t/src/good.tar.gz
  check() { if [ "$1" = 0 ]; then pass=$((pass + 1)); echo "ok   $2"; else fail=$((fail + 1)); echo "FAIL $2"; fi; }
  # 1. fresh good download: rc 0, file in place, path printed, no .part
  out=$(fetch_tarball "$good" "$goodsha" "$t/d1" x.tar.gz 2>/dev/null); rc=$?
  [ $rc = 0 ] && [ "$out" = "$t/d1/x.tar.gz" ] && cmp -s "$t/d1/x.tar.gz" "$t/src/good.tar.gz" && [ ! -e "$t/d1/x.tar.gz.part" ]
  check $? "good download is kept and its path printed"
  # 2. bad sha256: rc 1, nothing left in the directory
  fetch_tarball "$bad" "$goodsha" "$t/d2" x.tar.gz >/dev/null 2>&1; rc=$?
  [ $rc = 1 ] && [ -z "$(ls -A "$t/d2")" ]
  check $? "download with a wrong sha256 aborts and leaves no file"
  # 3. cached good file, URL unreachable: rc 0 without download
  mkdir "$t/d3"; cp "$t/src/good.tar.gz" "$t/d3/x.tar.gz"
  out=$(fetch_tarball "file://$t/src/missing" "$goodsha" "$t/d3" x.tar.gz 2>&1 >/dev/null); rc=$?
  [ $rc = 0 ] && ! grep -q downloading <<<"$out" && cmp -s "$t/d3/x.tar.gz" "$t/src/good.tar.gz"
  check $? "a cached good file is not downloaded again"
  # 4. cached bad file: deleted and downloaded again
  mkdir "$t/d4"; cp "$t/src/bad.tar.gz" "$t/d4/x.tar.gz"
  fetch_tarball "$good" "$goodsha" "$t/d4" x.tar.gz >/dev/null 2>&1; rc=$?
  [ $rc = 0 ] && cmp -s "$t/d4/x.tar.gz" "$t/src/good.tar.gz"
  check $? "a cached file with a wrong sha256 is replaced"
  # 5. cached bad file and a bad download: both gone
  mkdir "$t/d5"; cp "$t/src/bad.tar.gz" "$t/d5/x.tar.gz"
  fetch_tarball "$bad" "$goodsha" "$t/d5" x.tar.gz >/dev/null 2>&1; rc=$?
  [ $rc = 1 ] && [ -z "$(ls -A "$t/d5")" ]
  check $? "a bad cached file and a bad download leave no file"
  # 6. download failure (curl --fail on a missing file): rc 1, no .part
  fetch_tarball "file://$t/src/missing" "$goodsha" "$t/d6" x.tar.gz >/dev/null 2>&1; rc=$?
  [ $rc = 1 ] && [ -z "$(ls -A "$t/d6")" ]
  check $? "a failed download leaves no file"
  # 7. a stale .part from an interrupted run is not taken as the tarball
  mkdir "$t/d7"; cp "$t/src/good.tar.gz" "$t/d7/x.tar.gz.part"
  fetch_tarball "file://$t/src/missing" "$goodsha" "$t/d7" x.tar.gz >/dev/null 2>&1; rc=$?
  [ $rc = 1 ] && [ -z "$(ls -A "$t/d7")" ]
  check $? "a stale .part is not reused"
  # 8. the CLI refuses an unknown option (exit 2)
  bash "$0" --bogus >/dev/null 2>&1; rc=$?
  [ $rc = 2 ]
  check $? "unknown option exits 2"
  echo "RESULT $([ $fail = 0 ] && echo PASS || echo FAIL) ($pass of $((pass + fail)))"
  [ $fail = 0 ]
}

out=./dl
while [ $# -gt 0 ]; do
  case $1 in
    --out) [ $# -ge 2 ] || { echo "fetch-openssl: --out needs a directory" >&2; exit 2; }; out=$2; shift 2 ;;
    --selftest) selftest; exit ;;
    -h|--help) sed -n '2,13p' "$0"; exit 0 ;;
    *) echo "fetch-openssl: unknown argument $1 (usage: fetch-openssl.sh [--out DIR] | --selftest)" >&2; exit 2 ;;
  esac
done
fetch_tarball "$OPENSSL_TAR_URL" "$TAR_SHA256" "$out" "$OPENSSL_TAR_NAME"
